head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf30661";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_beforeName", fn: function () { return String((dma_pageContext.get("beforeName") ?? "")); } },
        { childId: "ipt_comCode", fn: function () { return String((dma_pageContext.get("comCode") ?? "")); } },
        { childId: "ipt_comName", fn: function () { return String((dma_pageContext.get("comName") ?? "")); } },
        { childId: "cal_strDate", fn: function () { return String((dma_pageContext.get("strDate") ?? "")); } },
        { childId: "cal_endDate", fn: function () { return String((dma_pageContext.get("endDate") ?? "")); } },
        { childId: "ipt_stockRate1", fn: function () { return String((dma_pageContext.get("stockRate1") ?? "")); } },
        { childId: "ipt_stockRate2", fn: function () { return String((dma_pageContext.get("stockRate2") ?? "")); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function () {
    if ('null' === 'end') {

    }
    const f = (document.form || { elements: [] });
    if ('null' === '' && 'null' === '') {
        setPeriod('12');
    }
    if ($c.util.getComponent('dma_submitReq').get('beforeName')!== '') {
        self.before.innerHTML = $c.util.getComponent('dma_submitReq').get('beforeName');
    }
    if (($c.util.getComponent('rd_gubun').getValue() === '0')) {
        let id = $c.util.getComponent("item");
        $c.util.getComponent('ipt_comCode').readOnly = true;
        id.setDisabled(true);
    }
    if (($c.util.getComponent('rd_cnt').getValue() === '0') || ($c.util.getComponent('rd_cnt').getValue() === '1')) {
        id = $c.util.getComponent("id_img");
        id.innerHTML = "<img src='/img/person/person_search_ti07.gif'/>";
    } else {
        id = $c.util.getComponent("id_img");
        id.innerHTML = "<img src='/img/person/person_search_ti08.gif'/>";
    }
};

/**
 * @method
 * @name initField
 * @description init Field 처리
 * @returns {void}
 * @hidden N
 */
scwin.initField = function () {
    const f = (document.form || { elements: [] });
    f.name.value = "";
    f.birthday.value = "";
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf30661.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name rd_gubun_onclick
 * @description rd_gubun 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.rd_gubun_onclick = function(e){
    try {
        scwin.itemSelect($c.util.getComponent("rd_gubun"))

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30661.rd_gubun_onclick' }); }
};

/**
 * @method
 * @name ipt_comCode_onclick
 * @description ipt_comCode 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ipt_comCode_onclick = async function(e){
    try {
        scwin.initField();await scwin.clickItem();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf30661.ipt_comCode_onclick' }); }
};

/**
 * @method
 * @name ipt_comCode_onkeypress
 * @description ipt_comCode onkeypress 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_comCode_onkeypress = function(e){
    try {
        const ev = e;
        const event = ev;
        if (event.keyCode===13){scwin.searchCode('read'); return false;}

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30661.ipt_comCode_onkeypress' }); }
};

/**
 * @method
 * @name item_onclick
 * @description 「[없음]」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.item_onclick = function(e){
    try {
        go_Stock(2)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30661.item_onclick' }); }
};

/**
 * @method
 * @name rd_cnt_onclick
 * @description rd_cnt 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.rd_cnt_onclick = function(e){
    try {
        scwin.imgChange($c.util.getComponent("rd_cnt"))

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30661.rd_cnt_onclick' }); }
};scwin.ipt_stockRate1_onkeypress = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        if ($c.util.getKeyCode(event) < 48 || $c.util.getKeyCode(event) > 57){event.returnValue = false;}

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30661.ipt_stockRate1_onkeypress' }); }
};

/**
 * @method
 * @name ipt_stockRate2_onkeypress
 * @description ipt_stockRate2 onkeypress 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_stockRate2_onkeypress = function(e){
    try {
        const ev = e;
        const event = ev;
        if ($c.util.getKeyCode(event) < 48 || $c.util.getKeyCode(event) > 57){event.returnValue = false;}

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30661.ipt_stockRate2_onkeypress' }); }
};

/**
 * @method
 * @name btn_submit_onclick
 * @description btn_submit 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_submit_onclick = async function(e){
    try {
        await scwin.submit()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf30661.btn_submit_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_submit
 * @description submit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_submit = async function () {
    const sbmOptions = {
        id: "tx_submit",
        method: "post",
        action: "/PersonInfo.do",
        ref: "dma_submitReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name submit
 * @description submit 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.submit = async function () {
    const f = (document.form || { elements: [] });
    if (($c.util.getComponent('rd_gubun').getValue() === '1') && ($c.util.getComponent('ipt_comCode').getValue() == null ? '' : String($c.util.getComponent('ipt_comCode').getValue())) === '') {
        await $c.win.alert("종목코드를 입력하셔야 합니다.");
        return;
    }
    f.action = "/PersonInfo.do";
    $c.util.getComponent('dma_submitReq').set('method', "statisticsSearchList");
    $c.util.getComponent("ipt_comName").setValue(encodeURI($c.util.getComponent('ipt_comName').getValue()));
    $c.util.getComponent('dma_submitReq').set('beforeName', encodeURI($c.util.getComponent('dma_submitReq').get('beforeName')));
    if ($c.num.isNumber($c.util.getComponent('ipt_comCode').getValue()) && $c.util.getComponent('ipt_comCode').getValue().length === 6) {
        $c.util.getComponent("ipt_comCode").setValue("A" + $c.util.getComponent('ipt_comCode').getValue());
    }
    if ((document.form || { elements: [] }).regcncl[1].checked) {
        /* 수동 전환 필요: regcncl[0].value 대입 — 그룹 항목 값은 옵션표가 정한다 */
    } else {
        /* 수동 전환 필요: regcncl[0].value 대입 — 그룹 항목 값은 옵션표가 정한다 */
    }
    await scwin.tx_submit();

};

/**
 * @method
 * @name itemSelect
 * @description item Select 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.itemSelect = function (obj) {
    const f = (document.form || { elements: [] });
    const id = $c.util.getComponent("item");
    if (obj.getValue() === '0') {
        $c.util.getComponent("ipt_comCode").setValue("");
        $c.util.getComponent("ipt_comName").setValue("");
        $c.util.getComponent('ipt_comCode').readOnly = true;
        id.setDisabled(true);
    } else {
        $c.util.getComponent('ipt_comCode').readOnly = false;
        id.setDisabled(false);
    }
};

/**
 * @method
 * @name imgChange
 * @description img Change 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.imgChange = function (obj) {
    const id = $c.util.getComponent("id_img");
    if (obj.getValue() === '0' || obj.getValue() === '1') {
        id.innerHTML = "<img src='/img/person/person_search_ti07.gif'/>";
    } else {
        id.innerHTML = "<img src='/img/person/person_search_ti08.gif'/>";
    }
};

/**
 * @method
 * @name clickItem
 * @description click Item 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.clickItem = async function () {
    if (($c.util.getComponent('rd_gubun').getValue() === '0')) {
        await $c.win.alert("구분에 종목을 선택해 주세요.");
    }
};

/**
 * @method
 * @name searchCode
 * @description search Code 처리
 * @param {*} searchValue searchValue
 * @returns {void}
 * @hidden N
 */
scwin.searchCode = function (searchValue) {
    let iCount = 0;
    arrReset();
    for (let j = 0; j < jr.length; j++) {
        if (searchValue === jr[j].jcode.substring(0, searchValue.length)) {
            if (jr[j].jname.indexOf("변경전사명") < 1) {
                if (regcncl === "1") {
                    arrCode[iCount] = jr[j].jcode;
                    arrName[iCount] = jr[j].jname;
                    iCount++;
                } else {
                    if (jr[j].jname.indexOf("폐지") < 1) {
                        arrCode[iCount] = jr[j].jcode;
                        arrName[iCount] = jr[j].jname;
                        iCount++;
                    }
                }
            }
        }
    }
    setSelectBox();
};
